/* Raises the timer while one of the ten targets is in the view cone, otherwise counts it down.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l12/gameplay/vendor/003028c8.c, FUN_L12_00303370. */
void update_hoven_turret_target_alignment_timer(void *moby) {
    Data_303370 *data = (Data_303370 *)((struct Moby *)moby)->pvars;
    int found = 0;
    int i;
    Vec4 position;

    for (i = 0; i < 10; i++) {
        if (data->targets[i] != -1) {
            Moby *target = &(*(Moby * *)&hoven_mobys_r2)[data->targets[i]];
            float yaw_limit;
            float pitch_limit;
            float yaw;
            float pitch;

            qcopy(&position, &target->pos);
            yaw_limit = 0.12217305f;
            pitch_limit = yaw_limit;
            if (target->oclass == 0x146)
                position.f[2] += 1.5f;
            if (target->oclass == 0x4FE) {
                yaw_limit = 0.034906585f;
                pitch_limit = 0.05235988f;
                position.f[2] += 1.5f;
            }
            yaw = fast_atan2(position.f[0] - hoven_player_camera.position.f[0], position.f[1] - hoven_player_camera.position.f[1]);
            pitch = fast_atan2(vec_distance_xy(&hoven_player_camera.position, &position), position.f[2] - hoven_player_camera.position.f[2]);
            if (FastDiffRots(yaw, hoven_player_camera.yaw) < yaw_limit &&
                FastDiffRots(pitch, -hoven_player_camera.pitch) < pitch_limit)
                found = 1;
        }
    }
    if (!found) {
        fast_dec_timer(&data->timer);
    } else {
        data->timer += 2;
        if (scale_ticks(30) < data->timer)
            data->timer = scale_ticks(30);
    }
}
