            d->f72 = 0;
            d->f78 = 0.0f;
            d->f7C = 0.0f;
            d->fA0 = moby->pos.z;
            d->f98 = -1;
            moby->rot.z = 3.1415927f;
            ((Snd_304920 *)(hero_globals_base_e + 0x1D))->f6C = moby;
