/* Moby update that pulses a glow tint on 18 linked mobys. */
void update_planetbuster_maximus_glow_color(char *moby) {
    struct Moby *self = (struct Moby *)moby;
    int i;
    int alpha = 0x80000000;
    char *data = (char *)self->pvars;
    for (i = 0; i < 18; i++) {
        struct Moby *other;
        int period;
        float sine;
        float color;
        int red;
        int green;
        int blue;
        int packed_color;
        float phase;
        float divisor;
        if (i == 17) {
            other = self;
        } else {
            other = (struct Moby *)((char *)hoven_mobys_r + ((unsigned int)*(int *)(data + i * 0x30 + 0x20) << 8));
        }
        if (other->oclass == 0x4FE) continue;
        {
            period = scale_ticks(0xAA);
            divisor = IntToFloat(period);
            phase = (float)(hoven_frame_count % period) / divisor;
            sine = FastSin((phase + phase) * 3.1415927f + -3.1415927f);
            color = sine * 70.0f;
            red = truncate_float_to_s32(color);
            green = truncate_float_to_s32(color);
            blue = truncate_float_to_s32(sine * 10.0f);
            packed_color = ((blue + 0x46) << 16) | alpha |
                ((green + 0xB4 > 0xFF ? 0xFF : green + 0xB4) << 8) |
                (red + 0xB4 > 0xFF ? 0xFF : red + 0xB4);
            other->flags |= 0x10;
            other->glow_color = packed_color;
        }
    }
}
