/* Pvars: d[0] is the moby to watch, d[1] the voice slot held for this moby.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l12/gameplay/vendor/003028c8.c, FUN_L12_003081b0. */
void update_moby_draw_and_monitor_linked_state(struct Moby *m) {
    int st = m->state;
    int vis;
    int *d = (int *)m->pvars;

    switch (st) {
    case 0:
        if (m->mission != 0xFF && saved_mission_state[m->mission + (*(s32 *)&g_current_level_index) * 16] == 0xFF) {
            DeleteMoby(m);
            break;
        }
        m->state = 1;
        break;
    case 1:
        vis = 1;
        if (check_scaled_vector_bsphere(m, 48.0f) == -1) {
            vis = 0;
        }
        if (vis) {
            AddDrawCallback(draw_hoven_jittered_quad_layers, m);
        }
        if (d[1] == -1) {
            d[1] = Moby_PlaySound_r(0, 4, m);
        }
        if (d[0] >= 0) {
            int i = d[1];
            char *e;
            if (i != -1) {
                e = voice_pool + i * 0x70;
                if (*(struct Moby **)(e + 0x88) == m && *(unsigned char *)(e + 0x74) != 0) {
                    Sound_StopSlot(i);
                }
            }
            e = (char *)((d[0] << 8) + (int)hoven_mobys);
            d[1] = -1;
            if (*(unsigned char *)(e + 0x20) == 7) {
                if (m->mission != 0xFF) {
                    jet_clear_persistent(m->mission);
                }
                Moby_PlaySound_r(1, 0, m);
                m->collision = 0;
                m->state = 2;
            }
        }
        break;
    }
}
