/* Picks cutscene moby slot 2 for step 1, else slot 0. */
static inline unsigned char func_L12_pick(int cur) {
    if (cur == 1) return 2;
    return 0;
}

/* Cutscene moby: on cinematic steps 1 and 7 aims the camera at a picked moby. */
void emit_phase_selected_moby_effects(Moby *moby) {
    Level12MobyList *list;
    Level12MobyList *l2;
    int cur;
    int k;
    switch (moby->state) {
    case 0:
        moby->update_dist = 0xFF;
        moby->state = 1;
        break;
    case 1:
        if (hoven_cinematic_mode == 2) {
            list = &hoven_cutscene_state;
            cur = list->current;
            if (cur == 1 || cur == 7) {
                k = func_L12_pick(cur);
                l2 = &hoven_cutscene_state;
                cutscene_set_camera_target((int)l2->mobys[k]);
            }
        }
        break;
    }
}
