/* Draws the moby's 10-piece overlay when its trigger is visible, with its own GS state. */
void draw_hoven_scrolling_texture_layers(char *m) {
    int *d = ((int *)((Moby *)m)->pvars);
    int i;
    font_queue_vu_state();
    VU1_addGSregister(0x42, 0x7F00000064L);
    VU1_addGSregister(8, 0);
    VU1_addGSregister(0x14, 0xFF9000000260L);
    VU1_addGSregister(0x47, 0x5360A);
    if (is_point_inside_clip_volume(hoven_camera_pos, d[0])) {
        VU1_addGSregister(6, GetEffectTex(0x2C));
        for (i = 0; i < 10; i++) {
            add_uv_scroll_offset(hoven_overlay_uv_buffer, hoven_overlay_piece_uvs[i], hoven_overlay_piece_vertex_counts[i], hoven_overlay_uv_scroll);
            draw_env_overlay_mesh(hoven_overlay_piece_vertex_counts[i], hoven_overlay_piece_meshes[i], hoven_overlay_piece_colors[i], hoven_overlay_uv_buffer, 1);
        }
    }
    VU1_addGSregister(6, GetEffectTex(0x2F));
    queue_oil_tanker_front_texture_2b_batches(0);
    VU1_addGSregister(0x42, ((long)hoven_scrolling_second_layer_fixed_alpha << 32) | 0x68);
    VU1_addGSregister(6, GetEffectTex(0x30));
    queue_oil_tanker_front_texture_2b_batches(1);
}
